const client=supabase.createClient(window.BUSINESSOS_SUPABASE_URL,window.BUSINESSOS_SUPABASE_ANON_KEY);let products=[],cart=[],view='sale';const money=x=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(x/100);const toast=t=>{const e=document.querySelector('#toast');e.textContent=t;e.style.display='block';setTimeout(()=>e.style.display='none',3500)};const setMessage=t=>document.querySelector('#message').textContent=t;const theme=localStorage.getItem('businessos-pos-theme')||'light';document.documentElement.dataset.theme=theme;const themeStyle=document.createElement('style');themeStyle.textContent='[data-theme="dark"]{--ink:#edf2f7;--muted:#9aaabd;--line:#2a3a4e;--bg:#0e1726;--card:#142238;--accent:#9db9dc;--danger:#ed858c}[data-theme="dark"] body{background:radial-gradient(circle at 90% -10%,#243b5b,transparent 35%),var(--bg)}[data-theme="dark"] .card,[data-theme="dark"] .table-wrap{background:var(--card);color:var(--ink)}[data-theme="dark"] input,[data-theme="dark"] select{background:#0e1726;color:var(--ink);border-color:#3b4d64}[data-theme="dark"] .secondary{background:#20344f;color:#eef4fb;border-color:#49617d}#toast{position:fixed;right:24px;bottom:24px;z-index:20;background:#19304f;color:#fff;padding:12px 16px;border-radius:9px;display:none;box-shadow:0 10px 25px #0003}';document.head.appendChild(themeStyle);
async function init(){const {data}=await client.auth.getSession();if(data.session){document.querySelector('#auth').hidden=true;document.querySelector('#app').hidden=false;await loadProducts();render()}client.auth.onAuthStateChange(async(event,session)=>{if(session){document.querySelector('#auth').hidden=true;document.querySelector('#app').hidden=false;await loadProducts();render()}else if(event==='SIGNED_OUT'){location.reload()}})}
async function loadProducts(){const {data,error}=await client.from('products').select('*').eq('active',true).order('name');if(error){toast(error.message);return}products=data||[]}
function render(){document.querySelector('#title').textContent={sale:'Satış',products:'Ürünler',stock:'Stok hareketleri'}[view];document.querySelector('#content').innerHTML=views[view]();bind()}
const views={sale:()=>`<div class="sale-layout"><div class="card"><div class="search"><input id="barcode" placeholder="Barkod veya ürün ara" autofocus><button id="scan">Ekle</button></div><div class="product-grid">${products.map(p=>`<div class="card product" data-add="${p.id}">${p.image_url?`<img src="${p.image_url}" alt="">`:'<div class="product-img"></div>'}<strong>${p.name}</strong><small>${money(p.sale_price_minor)} · Stok ${p.stock_quantity}</small></div>`).join('')||'<p class="empty">Henüz ürün yok. Ürünler ekranından ekleyin.</p>'}</div></div><div class="card"><h2>Sepet</h2>${cart.map(x=>`<div class="cart-line"><span>${x.name} × ${x.quantity}</span><strong>${money(x.sale_price_minor*x.quantity)}</strong></div>`).join('')||'<p class="empty">Ürün seçin veya barkod okutun.</p>'}<div class="cart-total"><span>Toplam</span><span>${money(cart.reduce((a,x)=>a+x.sale_price_minor*x.quantity,0))}</span></div><div class="pay-buttons"><button data-pay="cash">Nakit</button><button data-pay="card" class="secondary">Kredi kartı</button></div></div></div>`,products:()=>`<form class="card form" id="productForm"><label>Ürün adı<input name="name" required></label><label>Barkod<input name="barcode" required></label><label>Alış maliyeti<input name="cost" type="number" step="0.01" required></label><label>Satış fiyatı<input name="price" type="number" step="0.01" required></label><label>KDV oranı<select name="vat"><option value="1">%1</option><option value="10">%10</option><option value="20" selected>%20</option></select></label><label>Başlangıç stoğu<input name="stock" type="number" value="0" required></label><div class="full"><button>Ürün ekle</button></div></form><div class="table-wrap"><table class="table"><thead><tr><th>Ürün</th><th>Barkod</th><th>Satış</th><th>Stok</th><th>KDV</th></tr></thead><tbody>${products.map(p=>`<tr><td>${p.name}</td><td>${p.barcode}</td><td>${money(p.sale_price_minor)}</td><td>${p.stock_quantity}</td><td>%${p.vat_rate}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Ürün yok.</td></tr>'}</tbody></table></div>`,stock:()=>`<div class="card"><h2>Stok hareketleri</h2><p class="empty">Stok giriş/çıkış geçmişi bu alanda gösterilecek.</p></div>`,settings:()=>`<div class="card"><h2>Görünüm ayarları</h2><p class="muted">POS panelinin temasını seçin.</p><label>Tema<select id="posTheme"><option value="light">Açık tema</option><option value="dark">Karanlık tema</option></select></label></div>`};
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addToCart(b.dataset.add));document.querySelector('#scan')?.addEventListener('click',()=>{const q=document.querySelector('#barcode').value.trim(),p=products.find(x=>x.barcode===q)||products.find(x=>x.name.toLowerCase().includes(q.toLowerCase()));if(p)addToCart(p.id);else toast('Ürün bulunamadı')});document.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>completeSale(b.dataset.pay));const f=document.querySelector('#productForm');if(f)f.onsubmit=addProduct}
function addToCart(pid){const p=products.find(x=>x.id===pid);if(!p)return;const line=cart.find(x=>x.id===pid),nextQuantity=(line?.quantity||0)+1;if(Number(p.stock_quantity)<=0)return toast(`${p.name} stokta yok`);if(nextQuantity>Number(p.stock_quantity))return toast(`${p.name} için yeterli stok yok`);if(line)line.quantity=nextQuantity;else cart.push({...p,quantity:1});render()}
async function completeSale(method){if(!cart.length){toast('Sepet boş');return}const total=cart.reduce((a,x)=>a+x.sale_price_minor*x.quantity,0);const {data:{user}}=await client.auth.getUser();const {data:members}=await client.from('workspace_members').select('workspace_id').eq('user_id',user.id).limit(1);if(!members?.[0]){toast('İşletme alanı bulunamadı');return}const workspace_id=members[0].workspace_id;const {data:sale,error}=await client.from('sales').insert({workspace_id,total_minor:total,payment_method:method,status:method==='cash'?'paid':'pending'}).select().single();if(error){toast(error.message);return}for(const x of cart){await client.from('sale_items').insert({sale_id:sale.id,workspace_id,product_id:x.id,quantity:x.quantity,unit_price_minor:x.sale_price_minor,vat_rate:x.vat_rate});await client.from('products').update({stock_quantity:x.stock_quantity-x.quantity}).eq('id',x.id);await client.from('inventory_movements').insert({workspace_id,product_id:x.id,type:'sale',quantity:-x.quantity,reference_id:sale.id})}await client.from('transactions').insert({workspace_id,type:'income',date:new Date().toISOString().slice(0,10),description:`POS satışı #${sale.id.slice(0,8)}`,category:'POS Satış',amount_minor:total});cart=[];await loadProducts();render();toast(method==='card'?'POS ödemesi bekliyor olarak kaydedildi':'Nakit satış kaydedildi')}
async function addProduct(e){e.preventDefault();const d=new FormData(e.target),name=String(d.get('name')||'').trim(),barcode=String(d.get('barcode')||'').trim(),cost=Number(d.get('cost')),price=Number(d.get('price')),stock=Number(d.get('stock'));if(!name||!barcode||!Number.isFinite(cost)||!Number.isFinite(price)||!Number.isFinite(stock)){toast('Ürün adı, barkod ve geçerli fiyat/stock bilgisi gerekli');return}try{const {data:{user},error:userError}=await client.auth.getUser();if(userError||!user)throw userError||new Error('Oturum bulunamadı');const {data:members,error:memberError}=await client.from('workspace_members').select('workspace_id').eq('user_id',user.id).limit(1);if(memberError)throw memberError;if(!members?.[0])throw new Error('Bu kullanıcı için işletme alanı bulunamadı');const {error}=await client.from('products').insert({workspace_id:members[0].workspace_id,name,barcode,cost_minor:Math.round(cost*100),sale_price_minor:Math.round(price*100),vat_rate:Number(d.get('vat')),stock_quantity:stock,active:true});if(error)throw error;await loadProducts();render();toast('Ürün eklendi')}catch(error){console.error('Product insert failed',error);toast('Ürün eklenemedi: '+(error.message||'Supabase bağlantı/policy hatası'))}}
const settingsNav=document.createElement('button');settingsNav.dataset.view='settings';settingsNav.textContent='⚙ Ayarlar';document.querySelector('nav').appendChild(settingsNav);
document.addEventListener('change',e=>{if(e.target.id==='posTheme'){document.documentElement.dataset.theme=e.target.value;localStorage.setItem('businessos-pos-theme',e.target.value)}});const originalRender=render;render=()=>{originalRender();const select=document.querySelector('#posTheme');if(select)select.value=localStorage.getItem('businessos-pos-theme')||'light'};
views.stock=()=>`<div class="card"><h2>Stok giriş / çıkış</h2><form id="stockForm" class="form"><label>Ürün<select name="productId" required>${products.map(p=>`<option value="${p.id}">${p.name} · mevcut ${p.stock_quantity}</option>`).join('')}</select></label><label>İşlem türü<select name="type"><option value="purchase">Stok girişi</option><option value="adjustment">Stok çıkışı</option></select></label><label>Miktar<input name="quantity" type="number" min="1" step="1" required></label><label>Açıklama<input name="note" placeholder="Tedarikçi, sayım vb."></label><div class="full"><button>Stok hareketini kaydet</button></div></form></div><div class="table-wrap"><table class="table"><thead><tr><th>Ürün</th><th>Barkod</th><th>Mevcut stok</th><th>Alış maliyeti</th><th>Satış fiyatı</th></tr></thead><tbody>${products.map(p=>`<tr><td>${p.name}</td><td>${p.barcode}</td><td>${p.stock_quantity}</td><td>${money(p.cost_minor)}</td><td>${money(p.sale_price_minor)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Ürün yok.</td></tr>'}</tbody></table></div>`;
document.addEventListener('submit',async e=>{if(e.target.id!=='stockForm')return;e.preventDefault();const d=new FormData(e.target),product=products.find(x=>x.id===d.get('productId')),quantity=Number(d.get('quantity'));if(!product||!Number.isFinite(quantity)||quantity<=0)return toast('Geçerli bir ürün ve miktar seçin');const isPurchase=d.get('type')==='purchase';const delta=isPurchase?quantity:-quantity;if(Number(product.stock_quantity)+delta<0)return toast('Stok eksiye düşemez');const {error}=await client.from('products').update({stock_quantity:Number(product.stock_quantity)+delta}).eq('id',product.id);if(error)return toast('Stok güncellenemedi: '+error.message);const {data:{user}}=await client.auth.getUser(),{data:members}=await client.from('workspace_members').select('workspace_id').eq('user_id',user.id).limit(1);if(members?.[0]){const workspace_id=members[0].workspace_id;await client.from('inventory_movements').insert({workspace_id,product_id:product.id,type:d.get('type'),quantity:delta,reference_id:null});if(isPurchase){const amount=Math.round(Number(product.cost_minor)*quantity);const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul'}).format(new Date());const tx={workspace_id,type:'expense',date,description:`Stok alımı: ${product.name}`,category:'Stok Alımı',amount_minor:amount};const {error:txError}=await client.from('transactions').insert(tx);if(txError)return toast('Stok güncellendi fakat nakit akışı kaydedilemedi: '+txError.message)}}await loadProducts();render();toast(isPurchase?'Stok alımı ve nakit çıkışı kaydedildi':'Stok hareketi kaydedildi')});
const paymentStyle=document.createElement('style');paymentStyle.textContent='.payment-modal{position:fixed;inset:0;z-index:2000;display:grid;place-items:center;background:#07111dcc;backdrop-filter:blur(8px)}.payment-modal .card{width:min(430px,calc(100% - 32px));text-align:center}.payment-modal .actions{display:grid;gap:10px;margin-top:20px}';document.head.appendChild(paymentStyle);function closePayment(){document.querySelector('#paymentModal')?.remove()}async function startPayment(method){if(!cart.length)return toast('Sepet boş');const total=cart.reduce((a,x)=>a+x.sale_price_minor*x.quantity,0),modal=document.createElement('div');modal.id='paymentModal';modal.className='payment-modal';modal.innerHTML=method==='cash'?`<div class="card"><h2>Nakit satış</h2><p>Toplam <strong>${money(total)}</strong>. Satışı tamamlamak istiyor musunuz?</p><div class="actions"><button id="confirmCash">Evet, satışı tamamla</button><button id="cancelPayment" class="secondary">Vazgeç</button></div></div>`:`<div class="card"><h2>POS ödemesi</h2><p>POS cihazından <strong>${money(total)}</strong> tutarı çekin.</p><p class="muted">Ödeme tamamlandıktan sonra aşağıdaki seçeneği kullanın.</p><div class="actions"><button id="confirmCard">Ödeme tamamlandı</button><button id="cancelPayment" class="secondary">Ödeme iptal edildi</button></div></div>`;document.body.appendChild(modal);document.querySelector('#cancelPayment').onclick=closePayment;document.querySelector('#confirmCash')?.addEventListener('click',async()=>{closePayment();await completeSale('cash')});document.querySelector('#confirmCard')?.addEventListener('click',async()=>{closePayment();await completeSale('card');const {data:{user}}=await client.auth.getUser(),{data:members}=await client.from('workspace_members').select('workspace_id').eq('user_id',user.id).limit(1);if(members?.[0]){const {data:last}=await client.from('sales').select('id').eq('workspace_id',members[0].workspace_id).order('created_at',{ascending:false}).limit(1).single();if(last)await client.from('sales').update({status:'paid'}).eq('id',last.id)}})}document.addEventListener('click',e=>{const pay=e.target.closest('[data-pay]');if(!pay)return;e.preventDefault();e.stopImmediatePropagation();startPayment(pay.dataset.pay)},true);
window.posSales=[];async function loadSales(){const {data:{user}}=await client.auth.getUser(),{data:members,error:memberError}=await client.from('workspace_members').select('workspace_id').eq('user_id',user.id).limit(1);if(memberError)return toast('Workspace okunamadı: '+memberError.message);if(!members?.[0])return toast('İşletme alanı bulunamadı');const workspaceId=members[0].workspace_id;const salesResult=await client.from('sales').select('*').eq('workspace_id',workspaceId).order('created_at',{ascending:false}).limit(100);const txResult=await client.from('transactions').select('*').eq('workspace_id',workspaceId).eq('category','POS Satış').order('created_at',{ascending:false}).limit(100);if(salesResult.error&&txResult.error)return toast('Geçmiş satışlar okunamadı: '+salesResult.error.message);const sales=salesResult.data||[],transactions=txResult.data||[];window.posSales=sales.length?sales:transactions.map(x=>({id:x.id,created_at:x.created_at||x.date,total_minor:x.amount_minor,payment_method:'cash',status:'paid'}));}
const renderSalesBinding=render;render=()=>{renderSalesBinding();const button=document.querySelector('nav button[data-view="sales"]');if(button)button.onclick=async()=>{view='sales';await loadSales();render()}};
