views.products=()=>{const critical=products.filter(p=>Number(p.stock_quantity)<=5);return `${critical.length?`<div class="card" style="border-left:4px solid var(--danger);margin-bottom:18px"><h2>Kritik stok uyarısı</h2><p class="muted">${critical.map(p=>`${p.name}: ${p.stock_quantity} adet`).join(' · ')}</p></div>`:''}<form class="card form" id="productForm"><label>Ürün adı<input name="name" required></label><label>Barkod<input name="barcode" required></label><label>Alış maliyeti<input name="cost" type="number" step="0.01" required></label><label>Satış fiyatı<input name="price" type="number" step="0.01" required></label><label>KDV oranı<select name="vat"><option value="1">%1</option><option value="10">%10</option><option value="20" selected>%20</option></select></label><label>Başlangıç stoğu<input name="stock" type="number" value="0" required></label><div class="full"><button>Ürün ekle</button></div></form><div class="table-wrap"><table class="table"><thead><tr><th>Ürün</th><th>Barkod</th><th>Satış</th><th>Stok</th><th>KDV</th><th>Durum</th></tr></thead><tbody>${products.map(p=>`<tr><td>${p.name}</td><td>${p.barcode}</td><td>${money(p.sale_price_minor)}</td><td class="${Number(p.stock_quantity)<=5?'negative':''}">${p.stock_quantity}</td><td>%${p.vat_rate}</td><td>${Number(p.stock_quantity)<=5?'<span class="negative">Kritik</span>':'<span class="positive">Normal</span>'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Ürün yok.</td></tr>'}</tbody></table></div>`};const criticalStyle=document.createElement('style');criticalStyle.textContent='.positive{color:var(--good)}.negative{color:var(--danger)}';document.head.appendChild(criticalStyle);render();
views.sales=()=>{const rows=window.posSales||[],total=rows.filter(x=>x.status==='paid').reduce((a,x)=>a+x.total_minor,0),cash=rows.filter(x=>x.payment_method==='cash'&&x.status==='paid').reduce((a,x)=>a+x.total_minor,0),card=rows.filter(x=>x.payment_method==='card'&&x.status==='paid').reduce((a,x)=>a+x.total_minor,0);return `<div class="grid"><div class="card"><div class="label">Toplam satış</div><div class="metric">${money(total)}</div></div><div class="card"><div class="label">Nakit</div><div class="metric">${money(cash)}</div></div><div class="card"><div class="label">Kart</div><div class="metric">${money(card)}</div></div><div class="card"><div class="label">Satış adedi</div><div class="metric">${rows.length}</div></div></div><div class="card section"><h2>Geçmiş Satışlar</h2><div class="table-wrap"><table class="table"><thead><tr><th>Tarih</th><th>Satış</th><th>Ödeme</th><th>Durum</th><th>Tutar</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString('tr-TR')}</td><td>#${x.id.slice(0,8)}</td><td>${x.payment_method==='cash'?'Nakit':'Kredi kartı'}</td><td>${x.status==='paid'?'Ödendi':'POS bekliyor'}</td><td>${money(x.total_minor)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Henüz satış yok.</td></tr>'}</tbody></table></div></div>`};const salesNav=document.createElement('button');salesNav.dataset.view='sales';salesNav.textContent='▤ Geçmiş Satışlar';salesNav.onclick=async()=>{view='sales';await loadSales();render()};document.querySelector('nav').appendChild(salesNav);
document.querySelector('#login').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button'),emailValue=document.querySelector('#email').value.trim(),passwordValue=document.querySelector('#password').value;button.disabled=true;setMessage('Giriş yapılıyor…');try{const {error}=await client.auth.signInWithPassword({email:emailValue,password:passwordValue});if(error)setMessage(error.message);else setMessage('Giriş başarılı, panel yükleniyor…')}catch(error){setMessage(error.message||'Giriş sırasında bağlantı hatası oluştu.')}finally{button.disabled=false}};document.querySelector('#logout').onclick=()=>client.auth.signOut();init();
