async function loadAllProducts(){const {data,error}=await client.from('products').select('*').order('name');if(error)return toast('Ürünler okunamadı: '+error.message);products=data||[]}
document.querySelectorAll('nav button[data-view="products"]').forEach(b=>b.addEventListener('click',async()=>{await loadAllProducts();render()}));
const receiptStyle=document.createElement('style');receiptStyle.textContent='.receipt-modal{position:fixed;inset:0;z-index:3000;background:#07111dcc;display:grid;place-items:center;padding:20px}.receipt-paper{background:#fff;color:#111;width:min(380px,100%);padding:24px;border-radius:10px;font-family:monospace;box-shadow:0 20px 60px #0006}.receipt-paper h2{text-align:center;margin:0 0 16px}.receipt-line{display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px dashed #bbb}.receipt-total{display:flex;justify-content:space-between;font-weight:700;font-size:18px;margin-top:16px}.receipt-actions{display:flex;gap:8px;margin-top:20px}.receipt-actions button{flex:1}@media print{body>*:not(.receipt-modal){display:none!important}.receipt-modal{position:static;background:#fff;padding:0}.receipt-paper{box-shadow:none;width:80mm;border-radius:0}}';document.head.appendChild(receiptStyle);
function showReceipt(snapshot,method){const total=snapshot.reduce((a,x)=>a+x.sale_price_minor*x.quantity,0),modal=document.createElement('div');modal.className='receipt-modal';modal.innerHTML=`<div class="receipt-paper"><h2>BusinessOS POS</h2><p style="text-align:center">Satış fişi</p><p>${new Date().toLocaleString('tr-TR')}</p>${snapshot.map(x=>`<div class="receipt-line"><span>${x.name} x${x.quantity}</span><span>${money(x.sale_price_minor*x.quantity)}</span></div>`).join('')}<div class="receipt-total"><span>TOPLAM</span><span>${money(total)}</span></div><p>Ödeme: ${method==='cash'?'Nakit':'Kredi kartı'}</p><div class="receipt-actions"><button id="printReceipt">Yazdır</button><button id="closeReceipt" class="secondary">Kapat</button></div></div>`;document.body.appendChild(modal);modal.querySelector('#printReceipt').onclick=()=>window.print();modal.querySelector('#closeReceipt').onclick=()=>modal.remove()}
const originalCompleteSale=completeSale;completeSale=async method=>{const snapshot=cart.map(x=>({...x}));await originalCompleteSale(method);if(snapshot.length&&!document.querySelector('#paymentModal'))showReceipt(snapshot,method)};
document.addEventListener('keydown',e=>{if(e.key!=='Enter'||e.target.id!=='barcode')return;e.preventDefault();const q=e.target.value.trim(),p=products.find(x=>x.barcode===q)||products.find(x=>x.name.toLowerCase().includes(q.toLowerCase()));if(p){addToCart(p.id);e.target.value=''}else toast('Ürün bulunamadı')});
const receiptSettings=()=>JSON.parse(localStorage.getItem('businessos-pos-receipt')||'{}');views.settings=()=>{const s=receiptSettings();return `<div class="card"><h2>Fiş ve işletme ayarları</h2><p class="muted">Bu bilgiler yazdırılan fişin üst kısmında görünür.</p><form id="receiptSettingsForm" class="form"><label>İşletme adı<input name="businessName" value="${s.businessName||''}" placeholder="Örnek İşletme"></label><label>Telefon<input name="phone" value="${s.phone||''}" placeholder="+90 555 555 55 55"></label><label>Adres<input name="address" value="${s.address||''}" placeholder="İşletme adresi"></label><label>Vergi numarası<input name="taxNumber" value="${s.taxNumber||''}" placeholder="Vergi numarası"></label><div class="full"><button>Fiş ayarlarını kaydet</button></div></form></div>`};document.addEventListener('submit',e=>{if(e.target.id!=='receiptSettingsForm')return;e.preventDefault();const d=new FormData(e.target);localStorage.setItem('businessos-pos-receipt',JSON.stringify(Object.fromEntries(d)));toast('Fiş ayarları kaydedildi')});
showReceipt=(snapshot,method)=>{const s=receiptSettings(),total=snapshot.reduce((a,x)=>a+x.sale_price_minor*x.quantity,0),vat=snapshot.reduce((a,x)=>a+(x.sale_price_minor*x.quantity*(Number(x.vat_rate)||0)/(100+(Number(x.vat_rate)||0))),0),number=`POS-${Date.now().toString().slice(-8)}`,modal=document.createElement('div');modal.className='receipt-modal';modal.innerHTML=`<div class="receipt-paper"><h2>${s.businessName||'BusinessOS POS'}</h2>${s.address?`<p style="text-align:center">${s.address}</p>`:''}${s.phone?`<p style="text-align:center">${s.phone}</p>`:''}${s.taxNumber?`<p style="text-align:center">VKN: ${s.taxNumber}</p>`:''}<p>Fiş no: ${number}</p><p>${new Date().toLocaleString('tr-TR')}</p>${snapshot.map(x=>`<div class="receipt-line"><span>${x.name} x${x.quantity}</span><span>${money(x.sale_price_minor*x.quantity)}</span></div>`).join('')}<div class="receipt-line"><span>KDV</span><span>${money(vat)}</span></div><div class="receipt-total"><span>TOPLAM</span><span>${money(total)}</span></div><p>Ödeme: ${method==='cash'?'Nakit':'Kredi kartı'}</p><div class="receipt-actions"><button id="printReceipt">Yazdır</button><button id="closeReceipt" class="secondary">Kapat</button></div></div>`;document.body.appendChild(modal);modal.querySelector('#printReceipt').onclick=()=>window.print();modal.querySelector('#closeReceipt').onclick=()=>modal.remove()};
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-sale-cancel-paid]');if(!btn)return;e.preventDefault();const saleId=btn.dataset.saleCancelPaid;if(!confirm('Bu tamamlanmış satışı iptal etmek istediğinize emin misiniz? Stok geri eklenecek ve finans kayıtları tersine çevrilecek.'))return;const {data:items,error:itemError}=await client.from('sale_items').select('*').eq('sale_id',saleId);if(itemError)return toast('Satış kalemleri okunamadı: '+itemError.message);for(const item of items||[]){const {data:p}=await client.from('products').select('stock_quantity').eq('id',item.product_id).single();if(p)await client.from('products').update({stock_quantity:Number(p.stock_quantity)+Number(item.quantity)}).eq('id',item.product_id);await client.from('inventory_movements').insert({workspace_id:item.workspace_id,product_id:item.product_id,type:'return',quantity:item.quantity,reference_id:saleId})}const {data:sale}=await client.from('sales').select('workspace_id').eq('id',saleId).single();if(sale){await client.from('transactions').delete().eq('workspace_id',sale.workspace_id).like('description',`POS satışı #${saleId.slice(0,8)}%`);await client.from('transactions').delete().eq('workspace_id',sale.workspace_id).like('description',`POS satış maliyeti #${saleId}%`)}const {error}=await client.from('sales').update({status:'cancelled'}).eq('id',saleId);if(error)return toast('Satış iptal edilemedi: '+error.message);await loadSales();render();toast('Satış iptal edildi, stok geri eklendi')});
const salesViewWithCancel=views.sales;views.sales=()=>{const rows=window.posSales||[],paid=rows.filter(x=>x.status==='paid'),total=paid.reduce((a,x)=>a+x.total_minor,0);return `<div class="grid"><div class="card"><div class="label">Toplam satış</div><div class="metric">${money(total)}</div></div><div class="card"><div class="label">Satış adedi</div><div class="metric">${paid.length}</div></div></div><div class="card section"><h2>Geçmiş Satışlar</h2><div class="table-wrap"><table class="table"><thead><tr><th>Tarih</th><th>Satış</th><th>Ödeme</th><th>Durum</th><th>Tutar</th><th>İşlem</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString('tr-TR')}</td><td>#${x.id.slice(0,8)}</td><td>${x.payment_method==='cash'?'Nakit':'Kredi kartı'}</td><td>${x.status==='paid'?'<span class="positive">Ödendi</span>':x.status==='cancelled'?'<span class="negative">İptal edildi</span>':'<span class="negative">POS bekliyor</span>'}</td><td>${money(x.total_minor)}</td><td>${x.status==='paid'?`<button class="danger" data-sale-cancel-paid="${x.id}">Satışı iptal et</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Henüz satış yok.</td></tr>'}</tbody></table></div></div>`};
async function restoreAndCancelSale(saleId){const {data:items,error:itemError}=await client.from('sale_items').select('*').eq('sale_id',saleId);if(itemError)throw itemError;for(const item of items||[]){const {data:p,error:productError}=await client.from('products').select('stock_quantity').eq('id',item.product_id).single();if(productError)throw productError;const {error:updateError}=await client.from('products').update({stock_quantity:Number(p.stock_quantity)+Number(item.quantity)}).eq('id',item.product_id);if(updateError)throw updateError;const {error:movementError}=await client.from('inventory_movements').insert({workspace_id:item.workspace_id,product_id:item.product_id,type:'return',quantity:item.quantity,reference_id:saleId});if(movementError)throw movementError}const {data:sale,error:saleError}=await client.from('sales').select('workspace_id').eq('id',saleId).single();if(saleError)throw saleError;await client.from('transactions').delete().eq('workspace_id',sale.workspace_id).like('description',`POS satışı #${saleId.slice(0,8)}%`);await client.from('transactions').delete().eq('workspace_id',sale.workspace_id).like('description',`POS satış maliyeti #${saleId}%`);const {error}=await client.from('sales').update({status:'cancelled'}).eq('id',saleId);if(error)throw error}
document.addEventListener('click',async e=>{const toggle=e.target.closest('[data-toggle-product]');if(toggle){e.preventDefault();e.stopImmediatePropagation();const p=products.find(x=>x.id===toggle.dataset.toggleProduct);if(!p)return;const next=p.active===false;if(!confirm(next?'Bu ürünü tekrar aktifleştirmek istiyor musunuz?':'Bu ürünü pasife almak istiyor musunuz?'))return;const {error}=await client.from('products').update({active:next}).eq('id',p.id);if(error)return toast('Ürün durumu güncellenemedi: '+error.message);await loadAllProducts();render();toast(next?'Ürün aktifleştirildi':'Ürün pasife alındı');return}const cancel=e.target.closest('[data-sale-cancel-paid]');if(!cancel)return;e.preventDefault();e.stopImmediatePropagation();if(!confirm('Bu tamamlanmış satışı iptal etmek istediğinize emin misiniz? Ürünler stoğa geri eklenecek ve finans kayıtları geri alınacak.'))return;try{await restoreAndCancelSale(cancel.dataset.saleCancelPaid);await loadSales();render();toast('Satış iptal edildi, ürünler stoğa geri eklendi')}catch(error){toast('Satış iptal edilemedi: '+(error.message||'işlem hatası'))}},true);
